# Generate a graph with 14 vertices and exactly 33 edges
edges = []
count = 0
for u in range(14):
    for v in range(u+1, 14):
        if count < 33:
            edges.append((u, v))
            count += 1
        else:
            break
    if count >= 33:
        break

print(f"Number of edges: {len(edges)}")
print(f"Edges: {edges}")

# Verify all edges satisfy 0 <= u < v < 14
for u, v in edges:
    assert 0 <= u < v < 14, f"Invalid edge: ({u}, {v})"

print("All edges are valid!")
